import { Injectable } from '@angular/core';
import { TelemetryService } from '@honoregaming/customer-core';
import { SportsPoolGameState } from '@honoregaming/types';

@Injectable({ providedIn: 'root' })
export class SportsPoolTrackingService {
  constructor(private readonly telemetryService: TelemetryService) {}

  trackView(id: number, state: SportsPoolGameState, navigationSource: string): void {
    this.telemetryService.trackEvent('sportspool_view', { id, state, navigationSource });
  }

  trackSelection(id: number, params: SportsPoolSelectionParams & { isReserved: boolean }): void {
    this.telemetryService.trackEvent('sportspool_grid_selection', { id, ...params });
  }

  trackClearSelection(id: number): void {
    this.telemetryService.trackEvent('sportspool_grid_clear_selection', { id });
  }

  trackComplete(id: number, params: SportsPoolSelectionParams & { stakes: number }): void {
    this.telemetryService.trackEvent('sportspool_grid_complete', { id, ...params });
  }

  trackAddToCart(
    id: number,
    params: {
      doubleSelectedCount: number;
      tripleSelectedCount: number;
      stakes: number;
    }
  ): void {
    this.telemetryService.trackEvent('sportspool_grid_add_to_cart', { id, ...params });
  }

  trackFlash(id: number, flashType: string): void {
    this.telemetryService.trackEvent('sportspool_grid_flash', { id, flashType });
  }

  trackDisplayDetails(id: number, displayRanking: boolean): void {
    this.telemetryService.trackEvent('sportspool_grid_display_details', { id, displayRanking });
  }
}

export interface SportsPoolSelectionParams {
  doubleSelected: string;
  tripleSelected: string;
  matchsSelectedCount: string;
}
