import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Inject,
  Input,
  OnChanges,
  Output,
  SimpleChanges
} from '@angular/core';
import { SportsScoresService } from '@honoregaming/core';
import {
  EventStateDetailsType,
  EventStateType,
  Match,
  RegulationTimeScore,
  SelectableEventBetTypeItem,
  SelectedSportsPoolGameItem,
  SportsPoolGameMatch,
  SportsPoolGameState,
  ToggleSportsPoolGameBetEvent
} from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { ScoreWidgetComponent } from 'projects/core/hg-sports-ui/src/lib/components/score-widget/score-widget.component';

@Component({
  selector: 'hg-sports-pool-game-match',
  templateUrl: './sports-pool-game-match.component.html',
  styleUrls: ['./sports-pool-game-match.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolGameMatchComponent implements OnChanges {
  @Input() gameMatch!: SportsPoolGameMatch;
  @Input() gameState!: SportsPoolGameState;
  @Input() selectedItems: SelectedSportsPoolGameItem[] = [];

  @Output() toggleBet = new EventEmitter<ToggleSportsPoolGameBetEvent>();

  SportsPoolGameState = SportsPoolGameState;
  EventStateType = EventStateType;
  MatchDisplayState = MatchDisplayState;
  EventStateDetailsType = EventStateDetailsType;

  displayedScore?: RegulationTimeScore;
  isRegulationTimeOver: boolean = false;

  private static readonly PAUSE_STATES: ReadonlySet<EventStateDetailsType> = new Set([
    EventStateDetailsType.Pause,
    EventStateDetailsType.Pause1,
    EventStateDetailsType.Pause2,
    EventStateDetailsType.Pause3,
    EventStateDetailsType.Pause4,
    EventStateDetailsType.PauseOvertime
  ]);

  constructor(
    private readonly messageService: MessageService,
    private readonly sportsScoresService: SportsScoresService,
    @Inject(customerOperatorConfigurationToken) public readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.gameMatch) {
      this.isRegulationTimeOver =
        this.sportsScoresService.isOvertimeStateDetails(this.gameMatch.event.stateDetails) ||
        this.sportsScoresService.hasOvertimeScore(this.gameMatch.scores);
      this.displayedScore = this.sportsScoresService.computeDisplayedScore(this.gameMatch, this.isRegulationTimeOver);
    }
  }

  get isPaused(): boolean {
    return (
      !this.isRegulationTimeOver &&
      this.gameMatch.event.state === EventStateType.Started &&
      SportsPoolGameMatchComponent.PAUSE_STATES.has(this.gameMatch.event.stateDetails)
    );
  }

  get matchDisplayState(): MatchDisplayState {
    if (this.gameMatch.cancelled) {
      return MatchDisplayState.Cancelled;
    }

    if (this.gameMatch.delayed) {
      return MatchDisplayState.Postponed;
    }

    if (this.gameState === SportsPoolGameState.Undisputed) {
      return MatchDisplayState.BetTypes;
    }

    return MatchDisplayState.ShortName;
  }

  public openMatchInformations(event: Match): void {
    if (this.gameMatch.event.state !== EventStateType.Undisputed) {
      return;
    }
    this.messageService.sendComponentMessage(ScoreWidgetComponent, {
      event,
      sourceRef: event.sourceRef,
      configuration: this.operatorConfiguration,
      warnOnDataConsumption: true,
      displayTextWarnOnData: true
    });
  }

  public isSelected(ebti: { id: number }): boolean {
    return this.selectedItems.some(selectedSportsPoolGameItem => selectedSportsPoolGameItem.id === ebti.id);
  }

  toggleSelection(ebti: SelectableEventBetTypeItem, event: Event): void {
    this.toggleBet.emit({ eventBetTypeItem: ebti, event: event, matchPosition: this.gameMatch });
  }
}

export enum MatchDisplayState {
  BetTypes,
  ShortName,
  Cancelled,
  Postponed
}
