import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnInit,
  ChangeDetectorRef,
  Inject,
  OnDestroy,
  HostBinding
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import {
  SelectableEventBetTypeItem,
  SelectedSportsPoolGameItem,
  SportsPoolFlashType,
  SportsPoolGame,
  SportsPoolGameDetails,
  SportsPoolGameMatch,
  SportsPoolGameMatchLive,
  SportsPoolGameState,
  ToggleSportsPoolGameBetEvent
} from '@honoregaming/types';
import { finalize, switchMap, takeUntil } from 'rxjs/operators';
import { interval, Observable, Subscription } from 'rxjs';
import { BroadcastingService, DestroySubject, DialogService, LocalStorageService } from '@honoregaming/core';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { EventsService } from '@honoregaming/events';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { BetLine, BetSlipService, createSportsPoolBetLine } from '@honoregaming/betslip';
import { PopupSportsPoolGameDetailComponent } from 'projects/core/hg-sports-pool-ui/src/lib/components/popup-sports-pool-game-detail/popup-sports-pool-game-detail.component';
import { TutorialComponent } from 'projects/customer/hg-customer-ui/src/lib/components/tutorial/tutorial.component';
import { SportsPoolSelectionParams, SportsPoolTrackingService } from '../../services';

@Component({
  selector: 'hg-sports-pool-game',
  templateUrl: './sports-pool-game.component.html',
  styleUrls: ['./sports-pool-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolGameComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() public sportsPoolGame?: SportsPoolGame;

  public readonly SportsPoolGameState = SportsPoolGameState;
  public readonly SportsPoolFlashType = SportsPoolFlashType;

  public eventId?: number;
  public state?: SportsPoolGameState;
  public stakes?: number;
  public flashType?: SportsPoolFlashType;

  public reservedMatchs: SportsPoolGameMatch[] = [];
  public defaultMatchs: SportsPoolGameMatch[] = [];
  public hasReservedMatchs: boolean = false;

  public selectedItems: SelectedSportsPoolGameItem[] = [];
  public matchsSelectedCount: number = 0;
  public doubleSelectedCount: number = 0;
  public tripleSelectedCount: number = 0;

  public loading: boolean = false;
  public error: boolean = false;
  public showDetailsPopup: boolean = false;
  public displayRanking: boolean = false;
  public hasLiveMatch: boolean = false;

  public media?: Media;
  public Media = Media;

  public countdownText: string = '';
  private countdownSub?: Subscription;

  private liveSubscription?: Subscription;

  constructor(
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly messageService: MessageService,
    private readonly eventsService: EventsService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService,
    private readonly betSlipService: BetSlipService,
    private readonly mediaService: MediaService,
    private readonly broadcastingService: BroadcastingService,
    private readonly dialogService: DialogService,
    private readonly sportsPoolTrackingService: SportsPoolTrackingService,
    private readonly localStorageService: LocalStorageService,
    @Inject(customerOperatorConfigurationToken) public readonly operatorConfiguration: CustomerOperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.initializeRouteHandling();
    this.initializeMediaSubscription();
    this.initializeTutorial();
  }

  ngOnDestroy(): void {
    this.countdownSub?.unsubscribe();
    this.liveSubscription?.unsubscribe();
  }

  @HostBinding('class.empty')
  get isEmpty(): boolean {
    return !this.loading && !this.error && !this.sportsPoolGame;
  }

  get availableMatchCount(): number {
    return this.sportsPoolGame.matchPositions.length;
  }

  get isSelectionInvalid(): boolean {
    return (
      this.matchsSelectedCount === 0 ||
      this.matchsSelectedCount < this.availableMatchCount ||
      this.doubleSelectedCount > this.sportsPoolGame.details.maximumDoubleCount ||
      this.tripleSelectedCount > this.sportsPoolGame.details.maximumTripleCount
    );
  }

  get navigationSource(): 'bet_category' | 'navigation' | 'results' {
    const url: string[] = this.route.snapshot.url.map(urlSegment => urlSegment.path);

    if (url.includes('results')) return 'results';
    if (url.length > 0) return 'navigation';
    return 'bet_category';
  }

  get backgroundSrc(): string {
    const device = this.media <= Media.md ? 'mobile' : 'desktop';
    return `/assets/sports-pool/${device}-bg-state-${this.state}.png`;
  }

  getRouteLink(eventId: number): (string | number)[] {
    return this.navigationSource === 'results' ? ['/sports-pool', 'results', eventId] : ['/sports-pool', eventId];
  }

  toggleBet(
    { eventBetTypeItem, event, matchPosition }: ToggleSportsPoolGameBetEvent,
    isReserved: boolean = false
  ): void {
    event.preventDefault();
    event.stopImmediatePropagation();

    const selectedMatch: SelectedSportsPoolGameItem = {
      id: eventBetTypeItem.id,
      odds: eventBetTypeItem.odds,
      betTypeItemId: eventBetTypeItem.betTypeItemId,
      matchId: matchPosition.id,
      shortName: eventBetTypeItem.shortName,
      matchPosition: matchPosition.position,
      eventName: `${matchPosition.event.homeTeamName} - ${matchPosition.event.awayTeamName}`,
      eventId: matchPosition.event.id
    };

    const index: number = this.selectedItems.findIndex(item => item.id === selectedMatch.id);

    if (index === -1) {
      this.selectedItems.push(selectedMatch);
    } else {
      this.selectedItems.splice(index, 1);
    }

    this.updateCounts(isReserved);
  }

  clearSelectedItems(): void {
    this.selectedItems = [];
    this.updateCounts();
    this.sportsPoolTrackingService.trackClearSelection(this.sportsPoolGame.id);
  }

  runFlash(flashType: SportsPoolFlashType): void {
    const unselectedMatchPositions: SportsPoolGameMatch[] = this.getUnselectedMatchPositions();
    const isFullReset: boolean = unselectedMatchPositions.length === 0;

    this.selectedItems = isFullReset ? [] : [...this.selectedItems];

    const matchPositionsToFlash: SportsPoolGameMatch[] = isFullReset
      ? this.sportsPoolGame.matchPositions
      : unselectedMatchPositions;

    this.flashMatchPositions(matchPositionsToFlash, flashType);
    this.flashType = flashType;
    this.updateCounts();

    this.sportsPoolTrackingService.trackFlash(this.sportsPoolGame.id, flashType);
  }

  displaySportsPoolDetail(displayRanking = false): void {
    this.displayRanking = displayRanking;

    this.sportsPoolTrackingService.trackDisplayDetails(this.sportsPoolGame.id, displayRanking);

    if (this.isMobileView()) {
      this.openMobileDetails();
      return;
    }

    this.openDesktopDetails();
  }

  submitGrid(): void {
    const betLine: BetLine = createSportsPoolBetLine(
      this.sportsPoolGame,
      this.selectedItems,
      this.stakes,
      this.flashType
    );
    this.betSlipService.addBetLine(betLine);
    this.dialogService.toggleDialog('betslip', true);

    this.sportsPoolTrackingService.trackAddToCart(this.sportsPoolGame.id, {
      doubleSelectedCount: this.doubleSelectedCount,
      tripleSelectedCount: this.tripleSelectedCount,
      stakes: this.stakes
    });
  }

  trackByMatchId(_index: number, match: SportsPoolGameMatch): number {
    return match.id;
  }

  preventClick(event: Event): void {
    this.showDetailsPopup = false;
    event.preventDefault();
    event.stopPropagation();
  }

  private initializeRouteHandling(): void {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe({
      next: params => {
        this.eventId = params.eventId ? +params.eventId : null;
        this.loadEvent();
      },
      error: () => {
        this.error = true;
      }
    });
  }

  private initializeMediaSubscription(): void {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.media = media;
    });
  }

  private initializeTutorial(): void {
    if (this.localStorageService.getItem('tutorial:sportspool')) {
      return;
    }
    this.messageService
      .sendComponentMessage(
        TutorialComponent,
        { type: 'sportspool' },
        { canBeDismissed: false, displayClose: false, bare: true }
      )
      .closed.pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.localStorageService.setItem('tutorial:sportspool', true);
      });
  }

  private loadEvent(): void {
    this.setLoading(true);

    this.eventsService
      .getSportsPoolEvent(this.eventId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => this.setLoading(false))
      )
      .subscribe({
        next: event => this.handleLoadedEvent(event),
        error: () => (this.error = true)
      });
  }

  private setSportsPoolGameState(event: SportsPoolGame): void {
    const now: number = Date.now();
    const start: number = new Date(event.expectedStart).getTime();
    const end: number = new Date(event.expectedEnd).getTime();

    if (start > now) {
      this.state = SportsPoolGameState.Undisputed;
    } else if (end > now) {
      this.state = SportsPoolGameState.InProgress;
    } else {
      this.state = SportsPoolGameState.Finished;
    }
    this.broadcastingService.broadcast('display-betSlip-button-higher', this.state === SportsPoolGameState.Undisputed);
  }

  private setLoading(isLoading: boolean): void {
    this.loading = isLoading;
    this.cdRef.markForCheck();
  }

  private handleLoadedEvent(event: SportsPoolGame | null): void {
    if (!event) {
      return;
    }

    this.sportsPoolGame = event;
    this.eventId = event.id;
    this.stakes = event.details.baseAmount;
    this.handleInvalidMatchPositions();
    this.sortPoolRepartitions();
    this.setSportsPoolGameState(event);
    if (this.state !== SportsPoolGameState.Finished) {
      this.startCountdown();
    }

    this.setMatches(event.matchPositions);
    this.selectedItems = [];

    this.hasLiveMatch = this.hasLiveScores(event);
    if (this.hasLiveMatch) {
      this.subscribeToLiveScores();
    }

    this.updateCounts();
    this.sportsPoolTrackingService.trackView(this.sportsPoolGame.id, this.state, this.navigationSource);
  }

  private handleInvalidMatchPositions(): void {
    const hasEmptyMatchPosition: boolean = this.sportsPoolGame.matchPositions.some(matchPosition => !matchPosition);

    if (hasEmptyMatchPosition) {
      if (this.sportsPoolGame.nextId) {
        this.router.navigate(['/sports-pool', this.sportsPoolGame.nextId]);
        return;
      }

      this.error = true;
    }
  }

  private sortPoolRepartitions(): void {
    this.sportsPoolGame.details = {
      ...this.sportsPoolGame.details,
      poolRepartitions: [...this.sportsPoolGame.details.poolRepartitions].sort(
        (a, b) => b.winningMatchesCount - a.winningMatchesCount
      )
    };
  }

  private setMatches(sportsPoolGameMatches: SportsPoolGameMatch[]): void {
    this.defaultMatchs = sportsPoolGameMatches.filter(sportsPoolGameMatch => !sportsPoolGameMatch?.reserved);
    this.reservedMatchs = sportsPoolGameMatches.filter(sportsPoolGameMatch => sportsPoolGameMatch?.reserved);

    this.hasReservedMatchs = this.reservedMatchs.length > 0;
  }

  private hasLiveScores(event: SportsPoolGame): boolean {
    return event.matchPositions.some(match => !!match?.data);
  }

  private subscribeToLiveScores(): void {
    this.liveSubscription?.unsubscribe();

    this.liveSubscription = this.pollSportsPoolEventLive(this.eventId)
      .pipe(takeUntil(this.destroy$))
      .subscribe(liveMatches => {
        liveMatches.forEach(liveMatch => this.updateMatchDetails(liveMatch));
      });
  }

  private updateMatchDetails(liveMatch: SportsPoolGameMatchLive): void {
    const index: number = this.sportsPoolGame.matchPositions.findIndex(mp => mp.id === liveMatch.id);
    if (index === -1) return;

    const match: SportsPoolGameMatch = this.sportsPoolGame.matchPositions[index];

    this.sportsPoolGame.matchPositions[index] = {
      ...match,
      homeTeamScore: liveMatch.homeTeamScore,
      awayTeamScore: liveMatch.awayTeamScore,
      scores: liveMatch.scores ?? match.scores,
      data: liveMatch.isLive ? liveMatch.data : undefined,
      event: {
        ...match.event,
        stateDetails: liveMatch.isLive && liveMatch.stateDetails ? liveMatch.stateDetails : match.event.stateDetails
      }
    };

    this.setMatches(this.sportsPoolGame.matchPositions);
    this.cdRef.markForCheck();
  }

  private pickEbti(items: SelectableEventBetTypeItem[], flashType: SportsPoolFlashType): SelectableEventBetTypeItem {
    switch (flashType) {
      case SportsPoolFlashType.Random:
        return items[Math.floor(Math.random() * items.length)];
      case SportsPoolFlashType.BiggestDistribution:
        return items.reduce((max, item) => (item.betsDistribution > max.betsDistribution ? item : max), items[0]);
      case SportsPoolFlashType.LowestOdds:
        return items.reduce((min, item) => (item.odds < min.odds ? item : min), items[0]);
      case SportsPoolFlashType.HighestOdds:
        return items.reduce((max, item) => (item.odds > max.odds ? item : max), items[0]);
    }
  }

  private addSelectedEbti(ebti: SelectableEventBetTypeItem, matchPosition: SportsPoolGameMatch): void {
    this.selectedItems.push({
      id: ebti.id,
      odds: ebti.odds,
      betTypeItemId: ebti.betTypeItemId,
      matchId: matchPosition.id,
      shortName: ebti.shortName,
      matchPosition: matchPosition.position,
      eventName: `${matchPosition.event.homeTeamName} - ${matchPosition.event.awayTeamName}`,
      eventId: matchPosition.event.id
    });
  }

  private getUnselectedMatchPositions(): SportsPoolGameMatch[] {
    const selectedMatchIds: Set<number> = new Set(this.selectedItems.map(item => item.matchId));
    return this.sportsPoolGame.matchPositions.filter(matchPosition => !selectedMatchIds.has(matchPosition.id));
  }

  private flashMatchPositions(matchPositions: SportsPoolGameMatch[], flashType: SportsPoolFlashType): void {
    matchPositions.forEach(matchPosition => {
      const ebti: SelectableEventBetTypeItem = this.pickEbti(matchPosition.eventBetType.eventBetTypeItems, flashType);
      this.addSelectedEbti(ebti, matchPosition);
    });
  }

  private updateCounts(isReserved = false): void {
    this.matchsSelectedCount = new Set(
      this.selectedItems.map(selectedSportsPoolGameItem => selectedSportsPoolGameItem.matchId)
    ).size;

    const counts: Record<number, number> = this.selectedItems.reduce((acc, item) => {
      acc[item.matchId] = (acc[item.matchId] || 0) + 1;
      return acc;
    }, {} as Record<number, number>);

    this.doubleSelectedCount = Object.values(counts).filter(doubleSelectCount => doubleSelectCount === 2).length;
    this.tripleSelectedCount = Object.values(counts).filter(tripleSelectCount => tripleSelectCount === 3).length;
    this.updateStakes(counts);

    const selectionParams: SportsPoolSelectionParams = {
      doubleSelected: `${this.doubleSelectedCount}/${this.sportsPoolGame.details.maximumDoubleCount}`,
      tripleSelected: `${this.tripleSelectedCount}/${this.sportsPoolGame.details.maximumTripleCount}`,
      matchsSelectedCount: `${this.matchsSelectedCount}/${this.availableMatchCount}`
    };

    this.sportsPoolTrackingService.trackSelection(this.sportsPoolGame.id, { ...selectionParams, isReserved });

    if (!this.isSelectionInvalid) {
      this.sportsPoolTrackingService.trackComplete(this.sportsPoolGame.id, { ...selectionParams, stakes: this.stakes });
    }
  }

  private updateStakes(selectedLines: Record<number, number>): void {
    this.stakes = Object.values(selectedLines).reduce(
      (total, multiplier) => total * multiplier,
      this.sportsPoolGame.details.baseAmount
    );
  }

  private isMobileView(): boolean {
    return this.media <= Media.sm;
  }

  private openMobileDetails(): void {
    this.showDetailsPopup = true;
  }

  private openDesktopDetails(): void {
    this.messageService.sendComponentMessage(PopupSportsPoolGameDetailComponent, this.buildDetailPayload(), {
      bare: true
    });
  }

  private buildDetailPayload(): { details: SportsPoolGameDetails; isRanking: boolean } {
    return {
      details: this.sportsPoolGame.details,
      isRanking: this.displayRanking
    };
  }

  private startCountdown(): void {
    this.updateCountdown();
    if (this.countdownSub) {
      this.countdownSub.unsubscribe();
    }

    this.countdownSub = interval(1000).subscribe(() => {
      this.updateCountdown();
      this.cdRef.markForCheck();
    });
  }

  private updateCountdown(): void {
    const now: number = Date.now();
    const target: number = new Date(
      this.state === SportsPoolGameState.Undisputed
        ? this.sportsPoolGame.expectedStart
        : this.sportsPoolGame.expectedEnd
    ).getTime();
    let diff: number = target - now;

    if (diff <= 0) {
      this.countdownText = `00${this.i18nService.translateSync('COMMON.LABEL.DATE.S')}`;
      return;
    }

    const seconds: number = Math.floor(diff / 1000) % 60;
    const minutes: number = Math.floor(diff / (1000 * 60)) % 60;
    const hours: number = Math.floor(diff / (1000 * 60 * 60)) % 24;
    const days: number = Math.floor(diff / (1000 * 60 * 60 * 24));
    const pad = (n: number) => n.toString().padStart(2, '0');

    let text: string = '';
    if (days > 0) text += `${pad(days)}${this.i18nService.translateSync('COMMON.LABEL.DATE.D')} `;
    if (hours > 0 || days > 0) text += `${pad(hours)}${this.i18nService.translateSync('COMMON.LABEL.DATE.H')} `;
    if (minutes > 0 || hours > 0 || days > 0)
      text += `${pad(minutes)}${this.i18nService.translateSync('COMMON.LABEL.DATE.M')} `;
    text += `${pad(seconds)}${this.i18nService.translateSync('COMMON.LABEL.DATE.S')}`;

    this.countdownText = text.trim();
  }

  private pollSportsPoolEventLive(eventId: number): Observable<SportsPoolGameMatchLive[]> {
    return interval(60_000).pipe(switchMap(() => this.eventsService.getSportsPoolEventLive(eventId)));
  }
}
