import { Component, OnInit, ChangeDetectionStrategy, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformServer } from '@angular/common';
import { BetSlipService } from '@honoregaming/betslip';
import { BetCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent implements OnInit {
  public readonly isServer?: boolean;

  constructor(
    private readonly betSlipService: BetSlipService,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    this.isServer = isPlatformServer(this.platformId);
  }

  ngOnInit(): void {
    this.betSlipService.changeCurrentBetCategory(BetCategoryType.SportsPool);
  }
}
