import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { BroadcastingService, DestroySubject, DialogService } from '@honoregaming/core';

const BETSLIP_DIALOG_KEY: string = 'betslip';
const BETSLIP_HIGHER_EVENT: string = 'display-betSlip-button-higher';

@Component({
  selector: 'hg-sports-pool-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SidebarComponent extends DestroySubject implements OnInit {
  betSlipActive: boolean = false;
  hasAtLeastOneBetLine: boolean = false;
  isBetSlipHigher: boolean = false;

  constructor(
    private readonly dialogService: DialogService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly broadcastingService: BroadcastingService
  ) {
    super();
  }

  ngOnInit(): void {
    this.registerBetSlipDialog();
    this.registerBetSlipHigherBroadcast();
  }

  openBetSlip(): void {
    this.dialogService.toggleDialog(BETSLIP_DIALOG_KEY, !this.betSlipActive);
  }

  closeBetSlip(): void {
    this.dialogService.toggleDialog(BETSLIP_DIALOG_KEY, false);
  }

  hasBetLines(hasBetLines: boolean): void {
    this.hasAtLeastOneBetLine = hasBetLines;
  }

  private registerBetSlipDialog(): void {
    this.dialogService
      .registerDialog(BETSLIP_DIALOG_KEY)
      .pipe(takeUntil(this.destroy$))
      .subscribe((open: boolean) => {
        this.betSlipActive = open;
        this.cdRef.markForCheck();
      });
  }

  private registerBetSlipHigherBroadcast(): void {
    this.broadcastingService
      .register(BETSLIP_HIGHER_EVENT)
      .pipe(takeUntil(this.destroy$))
      .subscribe((value: boolean) => {
        this.isBetSlipHigher = value;
        this.cdRef.markForCheck();
      });
  }
}
