import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnInit,
  Output
} from '@angular/core';
import { Media, MediaService } from '@honoregaming/ui';
import { Tutorial, TutorialStep } from 'projects/customer/hg-core/src/lib/models/tutorial.model';
import { TUTORIALS } from 'projects/customer/customer/src/app/constants/tutorials.constant';

@Component({
  selector: 'hg-tutorial',
  templateUrl: './tutorial.component.html',
  styleUrls: ['./tutorial.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TutorialComponent implements OnInit {
  @Input() type!: string;

  @Output() close = new EventEmitter<{ disableReleaseBody: boolean }>();

  currentStepNumber: number = 0;
  steps: TutorialStep[] = [];

  constructor(private readonly mediaService: MediaService, private readonly cdr: ChangeDetectorRef) {}

  ngOnInit(): void {
    this.initSteps();
  }

  get currentTutorialStep(): TutorialStep | undefined {
    return this.steps[this.currentStepNumber];
  }

  get isFirstStep(): boolean {
    return this.currentStepNumber === 0;
  }

  get isLastStep(): boolean {
    return this.currentStepNumber === this.steps.length - 1;
  }

  goToStep(index: number): void {
    if (index >= this.steps.length) {
      this.closeTutorial();
      return;
    }

    if (index < 0) {
      return;
    }

    this.currentStepNumber = index;
    this.cdr.markForCheck();
  }

  private initSteps(): void {
    const tutorial: Tutorial | undefined = TUTORIALS.find(tutorial => tutorial.type === this.type);

    if (!tutorial) {
      this.closeTutorial();
      return;
    }

    this.steps = tutorial.steps;
  }

  private closeTutorial(): void {
    this.close.emit({
      disableReleaseBody: this.mediaService.media < Media.lg
    });
  }
}
