import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit } from '@angular/core';
import { finalize, takeUntil } from 'rxjs/operators';
import { BroadcastingService, DestroySubject } from '@honoregaming/core';
import { SportsPoolGameResult, SportsPoolResultsResponse } from '@honoregaming/types';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { EventsService } from '@honoregaming/events';

@Component({
  selector: 'hg-sports-pool-results',
  templateUrl: './results.component.html',
  styleUrls: ['./results.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SportsPoolResultsComponent extends DestroySubject implements OnInit {
  isLoading: boolean = true;
  isLoadingMore: boolean = false;
  error: boolean = false;
  hasMore: boolean = false;

  previousEvents: SportsPoolGameResult[] = [];
  currentEvents: SportsPoolGameResult[] = [];

  private pageIndex: number = 0;

  constructor(
    protected readonly cdRef: ChangeDetectorRef,
    private readonly eventsService: EventsService,
    private readonly broadcastingService: BroadcastingService,
    @Inject(operatorConfigurationToken) public readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.loadEvents();
    this.broadcastingService.broadcast('display-betSlip-button-higher', false);
  }

  loadMore(): void {
    this.pageIndex++;
    this.isLoadingMore = true;
    this.loadEvents();
  }

  private loadEvents(): void {
    this.eventsService
      .getSportsPoolGameResults(this.pageIndex)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => this.onLoadFinalize())
      )
      .subscribe(
        (sportsPoolResultsResponse: SportsPoolResultsResponse) => this.handleSuccess(sportsPoolResultsResponse),
        () => this.handleError()
      );
  }

  private handleSuccess(sportsPoolResultsResponse: SportsPoolResultsResponse): void {
    if (this.pageIndex === 0) {
      this.splitInitialEvents(sportsPoolResultsResponse.items);
    } else {
      this.appendMoreEvents(sportsPoolResultsResponse.items);
    }

    this.hasMore = sportsPoolResultsResponse.pagination.hasMore;
  }

  private splitInitialEvents(items: SportsPoolGameResult[]): void {
    this.previousEvents = items.filter(item => !item.inProgress);
    this.currentEvents = items.filter(item => item.inProgress);
  }

  private appendMoreEvents(items: SportsPoolGameResult[]): void {
    this.currentEvents.push(...items);
  }

  private handleError(): void {
    this.error = true;
  }

  private onLoadFinalize(): void {
    this.isLoading = false;
    this.isLoadingMore = false;
    this.cdRef.markForCheck();
  }
}
