import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { SidebarComponent } from './components/sidebar/sidebar.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { BetCategoriesGuard } from '@honoregaming/core';
import { BetCategoryType } from '@honoregaming/types';
import { SportsPoolGameComponent } from './containers/sports-pool-game/sports-pool-game.component';
import { SportsPoolResultsComponent } from './containers/results/results.component';
import { SportsPoolRulesComponent } from './containers/rules/rules.component';

const routes: Routes = [
  {
    path: '',
    data: { betCategories: BetCategoryType.SportsPool },
    canLoad: [BetCategoriesGuard],
    component: LayoutComponent,
    children: [
      { path: '', component: SportsPoolGameComponent },
      { path: 'results', component: SportsPoolResultsComponent },
      { path: 'results/:eventId', component: SportsPoolGameComponent },
      { path: 'rules', component: SportsPoolRulesComponent },
      { path: ':eventId', component: SportsPoolGameComponent }
    ]
  },
  { path: '', outlet: 'sidebar', component: SidebarComponent }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgSportsPoolRoutingModule {}
